from functools import lru_cache

NAME = "PaperRoute"
CHINESE_NAME = "选路译读"
VERSION = "0.1.0"
TITLE = f"{NAME} · {CHINESE_NAME}  {VERSION}"
QUOTE = "从来就只有一条我选的路，就算错了，那也是对"


@lru_cache(maxsize=1)
def ui_font_family():
    import os
    from pathlib import Path
    from PyQt5.QtGui import QFontDatabase
    fonts = Path(os.environ.get("WINDIR", "C:/Windows")) / "Fonts"
    for filename, preferred in (("msyh.ttc", "Microsoft YaHei UI"), ("segoeui.ttf", "Segoe UI")):
        path = fonts / filename
        if path.is_file():
            font_id = QFontDatabase.addApplicationFont(str(path))
            families = QFontDatabase.applicationFontFamilies(font_id)
            if families:
                return preferred if preferred in families else families[0]
    return "Microsoft YaHei"


@lru_cache(maxsize=1)
def quote_font_family():
    """Use installed calligraphy fonts; do not redistribute proprietary fonts."""
    import os
    from pathlib import Path
    from PyQt5.QtGui import QFontDatabase
    fonts = Path(os.environ.get("WINDIR", "C:/Windows")) / "Fonts"
    for filename in ("STXINGKA.TTF", "simkai.ttf"):
        path = fonts / filename
        if path.is_file():
            font_id = QFontDatabase.addApplicationFont(str(path))
            families = QFontDatabase.applicationFontFamilies(font_id)
            if families:
                return families[0]
    return "KaiTi"


def stylesheet(base_font=12, dpr_scale=1):
    from pdf2zh.local_config import APP_ROOT
    assets = (APP_ROOT / "assets").as_posix()
    f = max(9, round(base_font * dpr_scale))
    return f"""
    * {{ font-family: '{ui_font_family()}'; font-size: {f}px; color: #243548; }}
    QMainWindow {{ background: #F3F6FA; }}
    QFrame#Sidebar, QFrame#PreviewPanel {{ background: #FFFFFF; border: 1px solid #E2E9F1; border-radius: 14px; }}
    QLabel#BrandName {{ font-size: {f+11}px; font-weight: 700; color: #163D42; }}
    QLabel#BrandSubtitle {{ color: #738596; font-size: {f}px; }}
    QLabel#RouteQuote {{ font-family: '{quote_font_family()}', 'KaiTi', cursive; color: #526B76; font-size: {f+6}px; }}
    QLabel#PanelTitle {{ font-size: {f+4}px; font-weight: 600; color: #243548; padding: 2px 0 6px 0; }}
    QLabel#SectionCaption {{ color: #758598; font-size: {f}px; padding-top: 8px; }}
    QTabWidget::pane {{ border: none; background: transparent; }}
    QTabBar::tab {{ color: #8492A2; padding: 9px 14px; border: none; border-bottom: 2px solid transparent; background: transparent; }}
    QTabBar::tab:selected {{ color: #0F766E; font-weight: 600; border-bottom: 2px solid #0F766E; }}
    QPushButton, QToolButton {{ background: #FFFFFF; border: 1px solid #DDE5ED; border-radius: 6px; padding: 6px 9px; }}
    QPushButton:hover, QToolButton:hover {{ background: #F0F8F7; border-color: #8CBEB7; color: #0F766E; }}
    QPushButton:pressed, QToolButton:checked {{ background: #E4F1EF; }}
    QPushButton:disabled {{ background: #F4F6F8; border-color: #E8EDF2; color: #ABB6C2; }}
    QPushButton#translateBtn {{ background: #0F766E; border: 1px solid #0F766E; color: #FFFFFF; font-weight: 600; padding: 9px; }}
    QPushButton#translateBtn:hover {{ background: #0D665F; }}
    QPushButton#translateBtn:disabled {{ background: #B3CDC9; border-color: #B3CDC9; }}
    QFrame#ModelSaveBar {{ background: #EDF7F4; border: 1px solid #CFE7DF; border-radius: 9px; }}
    QPushButton#SaveModels {{ background: #0F766E; color: #FFFFFF; border: 1px solid #0F766E; font-weight: 600; padding: 11px 22px; }}
    QPushButton#SaveModels:hover {{ background: #0D665F; border-color: #0D665F; }}
    QLabel#SaveStatus {{ color: #638076; }}
    QLabel#SaveStatus[dirty="true"] {{ color: #B46312; font-weight: 600; }}
    QPushButton#QuietButton {{ border: none; background: transparent; color: #718293; padding: 5px 3px; }}
    QToolButton#AdvancedToggle {{ border: none; background: #F4F8FA; text-align: left; color: #5A7083; padding: 8px; }}
    QFrame#AdvancedPanel {{ background: #F7F9FC; border: 1px solid #E4EAF1; border-radius: 8px; }}
    QComboBox, QLineEdit, QSpinBox, QTextEdit, QPlainTextEdit {{ background: #FFFFFF; border: 1px solid #DDE5ED; border-radius: 6px; padding: 6px; selection-background-color: #D5EBE6; selection-color: #163D42; }}
    QComboBox:focus, QLineEdit:focus, QSpinBox:focus, QTextEdit:focus {{ border-color: #56A399; }}
    QComboBox QAbstractItemView {{ background: #FFFFFF; border: 1px solid #DDE5ED; selection-background-color: #E6F3EF; selection-color: #0F766E; padding: 4px; }}
    QComboBox::drop-down {{ subcontrol-origin: padding; subcontrol-position: top right; width: 18px; border: none; background: transparent; }}
    QComboBox::down-arrow {{ image: url("{assets}/chevron-down.svg"); width: 8px; height: 6px; }}
    QSpinBox::up-button {{ subcontrol-origin: border; subcontrol-position: top right; width: 16px; border: none; background: transparent; }}
    QSpinBox::down-button {{ subcontrol-origin: border; subcontrol-position: bottom right; width: 16px; border: none; background: transparent; }}
    QSpinBox::up-arrow {{ image: url("{assets}/chevron-up.svg"); width: 7px; height: 4px; }}
    QSpinBox::down-arrow {{ image: url("{assets}/chevron-down.svg"); width: 7px; height: 4px; }}
    QCheckBox {{ spacing: 6px; padding: 3px 0; }}
    QCheckBox::indicator {{ width: 12px; height: 12px; border: 1px solid #BBC9D5; border-radius: 3px; background: #FFFFFF; }}
    QCheckBox::indicator:checked {{ background: #0F766E; border-color: #0F766E; image: url("{assets}/checkmark.svg"); }}
    QScrollArea {{ border: none; background: transparent; }}
    QScrollBar:vertical {{ background: transparent; width: 7px; margin: 2px 0; }}
    QScrollBar::handle:vertical {{ background: #D5DEE7; border-radius: 3px; min-height: 24px; }}
    QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {{ height: 0; }}
    QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {{ background: transparent; }}
    QListWidget, QTableWidget {{ background: #FFFFFF; border: 1px solid #E2E9F1; border-radius: 7px; selection-background-color: #E5F2EF; selection-color: #183D40; }}
    QHeaderView::section {{ background: #F5F8FB; border: none; border-bottom: 1px solid #E2E9F1; padding: 7px; color: #526B7D; }}
    QProgressBar {{ background: #EAF0F5; border: none; border-radius: 3px; }}
    QProgressBar::chunk {{ background: #0F766E; border-radius: 3px; }}
    QToolTip {{ background: #FFFFFF; color: #334D5D; border: 1px solid #DDE5ED; padding: 8px; }}
    """


def show_about(parent):
    from PyQt5.QtWidgets import QDialog, QDialogButtonBox, QTextBrowser, QVBoxLayout

    dialog = QDialog(parent)
    dialog.setWindowTitle("关于 PaperRoute 与开源来源")
    dialog.resize(600, 430)
    layout = QVBoxLayout(dialog)
    text = QTextBrowser()
    text.setOpenExternalLinks(True)
    text.setHtml(f"""<h2>{NAME} · {CHINESE_NAME}</h2><p>版本 {VERSION}</p>
    <p>专注阅读与翻译的本地桌面改版：模型池自动故障切换、独立并发控制、简洁工作台。</p>
    <h3>来源与致谢</h3>
    <p>桌面程序参考 <a href="https://github.com/AaronGIG/pdf2zh-desktop">AaronGIG / pdf2zh-desktop</a>。<br>
    翻译核心来自 <a href="https://github.com/PDFMathTranslate/PDFMathTranslate">PDFMathTranslate</a>，
    排版相关组件包括 <a href="https://github.com/funstory-ai/BabelDOC">BabelDOC</a>。<br>
    感谢原作者和贡献者。PaperRoute 是独立改版，并非上述项目的官方发行版。</p>
    <h3>许可信息</h3>
    <p>PDFMathTranslate 与 BabelDOC 的随附许可证为 AGPL-3.0。
    新增 PaperRoute 代码同样提供 AGPL-3.0-only 许可；第三方组件保留各自许可。
    桌面外壳上游未找到明确的独立 LICENSE，公开再分发前仍需确认其授权范围。</p>
    <p>完整来源与变更记录见安装目录的 THIRD_PARTY_NOTICES.md 和 PUBLISHING.md。</p>""")
    layout.addWidget(text)
    buttons = QDialogButtonBox(QDialogButtonBox.Close)
    buttons.rejected.connect(dialog.reject)
    layout.addWidget(buttons)
    dialog.exec_()
